/// <summary>
/// Extension of Table class SalesConfirmDetailsTmp
/// </summary>
[ExtensionOf(tableStr(SalesConfirmDetailsTmp))]
 final class AVASalesConfirmDetailsTmpDbt_Extension
{
}

Method.Source:
/// <summary>
/// insert record
/// </summary>
public void insert()
{
    next insert();

    //copy of the SalesConfirmDetails from UsingExistingReportData()
    if(this.AVAOrigSalesConfirmDetailsTmp && this.AVAOrigSalesConfirmDetailsTmp != this.RecId)
    {
        AvaReportingMarkupTransTmp::resetIsCopy(this.TableId, this.AVAOrigSalesConfirmDetailsTmp, this.RecId);
    }
    else
    {
        //fill the markuptrans records
        CustConfirmTrans custConfirmTrans = CustConfirmTrans::findRecId(this.CustConfirmTrans);
        if(custConfirmTrans)
        {
            CustConfirmJour custConfirmJour = custConfirmTrans.custConfirmJour();
            boolean proforma = custConfirmJour.isProforma();
            SalesLine salesline = custConfirmTrans.salesLine();

            if(proforma)
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, salesline, custConfirmJour.LanguageId, proforma, custConfirmTrans.Qty, custConfirmTrans.LineAmount, 0.0, salesline.inclTax());
            }
            else
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, custConfirmTrans, custConfirmJour.LanguageId);
            }

        }
    }

    this.AVAOrigSalesConfirmDetailsTmp = this.RecId;
    this.doUpdate();
}
